110	     * Run the simulation from its current state for a single step.
111	     * Iterate over the whole field updating the state of each animal.
112	     */
113	    public void simulateOneStep()
114	    {
115	        step++;
116	        
117	        // Alternates between day and night time every 2 steps
118	        if (step > 2 && step % 2 == 1) {
119	            nightTime = !nightTime;
120	        }
121	        
122	        // Provide space for newborn organisms
123	        List<Actor> newOrganisms = new ArrayList<>();
124	        SimulationContext context = new SimulationContext(actors, newOrganisms, nightTime);
125	
126	        // Let all actors advance by one tick.
127	        Iterator<Actor> it = actors.iterator();
128	        while(it.hasNext()) {
129	            Actor actor = it.next();
130	            actor.tick(context);
131	            if (actor.isExpired()) {
132	                it.remove();
133	            }
134	        }
135	        // Add the newly born actors to the main list.
136	        actors.addAll(newOrganisms);
137	        
138	        // If it has rained, create new water
139	        if (context.shouldGenerateWater()) {
140	            generateWater();
141	        }
142	        
143	        view.showStatus(step, field);
144	    }
145	        
146	    /**
147	     * Reset the simulation to a starting position.
148	     */
149	    public void reset()
150	    {
151	        step = 0;
152	        actors.clear();
153	
154	        populate();
155	        nightTime = false;
156	        
157	        // Show the starting state in the view.
158	        view.showStatus(step, field);
159	    }
