161	    /**
162	     * Randomly populate the field with animals.
163	     */
164	    private void populate()
165	    {
166	        Random rand = Randomizer.getRandom();
167	        field.clear();
168	        
169	        // Creates default actors (diseases and weather)
170	        actors.add(new Covid(field));
171	        actors.add(new Leptospirosis(field));
172	        actors.add(new Weather());
173	        for(int row = 0; row < field.getDepth(); row++) {
174	            for(int col = 0; col < field.getWidth(); col++) {
175	                populateCell(rand, row, col);
176	            }
177	        }
178	    }
179	    
180	    /** 
181	     * Creates random water spaces in free locations in field
182	     * Used when it rains to create new water sources
183	     */
184	    public void generateWater()
185	    {
186	        Random rand = Randomizer.getRandom();
187	        for(int row = 0; row < field.getDepth(); row++) {
188	            for(int col = 0; col < field.getWidth(); col++) {
189	                // if there is an empty space, chance of creating a new water source
190	                if (rand.nextDouble() < LAKE_CREATION_PROBABILITY/120) {
191	                    addLakeCluster(new Location(row, col), rand, true);
192	                }
193	            }
194	        }
195	    }
196	
197	    /**
198	     * Populate one field cell according to the configured probabilities.
199	     * @param rand Shared random source.
200	     * @param row The row to populate.
201	     * @param col The column to populate.
202	     */
203	    private void populateCell(Random rand, int row, int col)
204	    {
205	        Location location = new Location(row, col);
206	        if(rand.nextDouble() <= LAKE_CREATION_PROBABILITY) {
207	            addLakeCluster(location, rand, false);
208	        }
209	        else if(rand.nextDouble() <= HYENA_CREATION_PROBABILITY) {
210	            actors.add(new Hyena(true, field, location));
211	        }
212	        else if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
213	            actors.add(new Lion(true, field, location));
214	        }
215	        else if(rand.nextDouble() <= GAZELLE_CREATION_PROBABILITY) {
216	            actors.add(new Gazelle(true, field, location));
217	        }
218	        else if(rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
219	            actors.add(new Mouse(true, field, location));
220	        }
221	        else if(rand.nextDouble() <= FENNECFOX_CREATION_PROBABILITY) {
222	            actors.add(new FennecFox(true, field, location));
223	        }
224	        else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
225	            actors.add(new Grass(true, field, location));
226	        }
227	    }
228	
229	    /**
230	     * Create a lake and optionally extend it to adjacent locations.
231	     * @param location The origin location.
232	     * @param rand Shared random source.
233	     * @param sparse Whether adjacent lake tiles should be created probabilistically.
234	     */
235	    private void addLakeCluster(Location location, Random rand, boolean sparse)
236	    {
237	        actors.add(new Lake(true, field, location));
238	        List<Location> adjacent = field.adjacentLocations(location);
239	        for (Location adjacentLocation : adjacent) {
240	            if (!sparse || rand.nextBoolean()) {
241	                actors.add(new Lake(true, field, adjacentLocation));
242	            }
243	        }
244	    }
