  8	/**
  9	 * Models a generic disease which can affect organisms and cause them to die
 10	 *
 11	 * @version 2022.02.28
 12	 */
 13	public abstract class Disease implements Actor
 14	{
 15	    // The field of the simulation
 16	    private Field field;
 17	    // A list of the species that the disease affects
 18	    private List<String> affectedSpecies;
 19	    // A hashmap containing organisms currently infected with disease
 20	    // and how long they've been infected for
 21	    private HashMap<Actor, Integer> affected;
 22	    // The probability of the disease randomly occuring in the population
 23	    private double probability;
 24	    // The probability of the disease spreading
 25	    private double infectiousness;
 26	    // How long the disease affects an infected organism for
 27	    private int duration;
 28	    // Randomiser to control random spread of disease
 29	    private static final Random rand = Randomizer.getRandom();
 30	    
 31	    /**
 32	     * Constructor for a disease
 33	     * 
 34	     * @param The field currently occupied
 35	     */
 36	    public Disease(Field field)
 37	    {
 38	        this.field = field;
 39	        affectedSpecies = new ArrayList<>();
 40	        affected = new HashMap<>();
 41	        probability = 0.0001;
 42	    }
 43	
 44	    /**
 45	     * Advance the disease by one lifecycle tick.
 46	     * Disease can infect susceptible actors, spread through the field, and resolve infections.
 47	     * @param context Shared lifecycle state for the current step.
 48	     */
 49	    @Override
 50	    public void tick(SimulationContext context)
 51	    {
 52	        infectSusceptibleActors(context.getActors());
 53	
 54	        List<Actor> infectedActors = new ArrayList<>(affected.keySet());
 55	        // Loops through every infected actor that was already active this tick.
 56	        Iterator<Actor> it = infectedActors.iterator();
 57	        List<Actor> newInfections = new ArrayList<>();
 58	        while (it.hasNext()) {
 59	            Actor infected = it.next();
 60	            newInfections.addAll(spread(infected));
 61	            if (affected.get(infected) == duration) {
 62	                affected.remove(infected);
 63	                if (infected instanceof Organism) {
 64	                    Organism organism = (Organism) infected;
 65	                    organism.setDead();
 66	                }
 67	                else {
 68	                    WaterSources water = (WaterSources) infected;
 69	                    water.notInfected();
 70	                }
 71	            }
 72	            else {
 73	                int days = affected.get(infected) + 1;
 74	                affected.put(infected, days);
 75	            }
 76	        }
 77	        for (Actor infectee: newInfections) {
 78	            if (infectee instanceof Organism) {
 79	                Organism organism = (Organism) infectee;
 80	                organism.setInfected();
 81	                affected.put(organism, 0);  
 82	            }
 83	            else if (infectee instanceof WaterSources)  {
 84	                WaterSources water = (WaterSources) infectee;
 85	                water.setInfected();
 86	                affected.put(water, 0);  
 87	            }
 88	        }
 89	    }
 90	    
 91	    /** 
 92	     * Spreads disease to nearby individuals who can be infected
 93	     * 
 94	     * @param The actor which is infected and spreads disease to 
 95	     * neighbouring individuals
 96	     */
 97	    public List<Actor> spread(Actor actor) {
 98	        List<Actor> newlyInfected = new ArrayList<>();
 99	        List<Location> adjacent = null;
100	        // looks at surrounding individuals and chance of infecting them if possible
101	        if (actor instanceof Organism) {
102	            Organism organism = (Organism) actor;
103	            if (organism.isAlive()) {
104	                adjacent = field.adjacentLocations(organism.getLocation());
105	            }
106	        }
107	        else if (actor instanceof WaterSources) {
108	            WaterSources water = (WaterSources) actor;
109	            if (!water.isEmpty()) {
110	                adjacent = field.adjacentLocations(water.getLocation());
111	            }
112	        }
113	        if(adjacent != null) {
114	            Iterator<Location> it = adjacent.iterator();
115	            while(it.hasNext()) {
116	                Location where = it.next();
117	                Object thing = field.getObjectAt(where);
118	                if (thing != null && affectedSpecies.contains(thing.getClass().getName())) {
119	                    if (rand.nextDouble() < infectiousness) {
120	                        if (thing instanceof Organism) {
121	                            Organism infectee = (Organism) thing;
122	                            newlyInfected.add(infectee);
123	                        }
124	                        else if (thing instanceof WaterSources) {
125	                            WaterSources infectee = (WaterSources) thing;
126	                            newlyInfected.add(infectee);
127	                        }
128	                    }
129	                }
130	            }
131	        }
132	        return newlyInfected;
133	    }
134	
135	    /**
136	     * Infect susceptible actors with the disease's random occurrence probability.
137	     * @param actors The actors available in the current simulation step.
138	     */
139	    private void infectSusceptibleActors(List<Actor> actors)
140	    {
141	        for (Actor actor : actors) {
142	            if (!affectedSpecies.contains(actor.getClass().getName())) {
143	                continue;
144	            }
145	            if (affected.containsKey(actor)) {
146	                continue;
147	            }
148	            if (actor instanceof Organism) {
149	                Organism organism = (Organism) actor;
150	                if (!organism.isAlive()) {
151	                    continue;
152	                }
153	            }
154	            else if (actor instanceof WaterSources) {
155	                WaterSources water = (WaterSources) actor;
156	                if (water.isEmpty()) {
157	                    continue;
158	                }
159	            }
160	            if (rand.nextDouble() <= probability) {
161	                addIndividual(actor);
162	                if (actor instanceof Organism) {
163	                    Organism organism = (Organism) actor;
164	                    organism.setInfected();
165	                }
166	                else if (actor instanceof WaterSources) {
167	                    WaterSources water = (WaterSources) actor;
168	                    water.setInfected();
169	                }
170	            }
171	        }
172	    }
173	    
174	    /**
175	     * Method to add species which can be infected with the disease
176	     * @param species Varargs so can take any number of species to be infected
177	     */
178	    protected void addSpecies(String... species) {
179	        Collections.addAll(affectedSpecies, species);
180	    }
181	    
182	    /** 
183	     * @return The  list of species affected by this disease
184	     */
185	    public List<String> getSpecies() {
186	        return affectedSpecies;
187	    }
188	    
189	    /**
190	     * Adds an infected individual to the list of those currently infected 
191	     * @actor Actor to be infected
192	     */
193	    public void addIndividual(Actor actor) {
194	        affected.put(actor, 0);
195	    }
196	    
197	    /**
198	     * Method to set probability of disease randomly occurring
199	     * @param Probability of disease occurring
200	     */
201	    protected void setProbability(double prob) {
202	        probability = prob;
203	    }
204	    
205	    /**
206	     * @return The probability of the disease randomly occuring
207	     */
208	    public double getProbability() {
209	        return probability;
210	    }
211	    
212	    /**
213	     * Method to set probability of disease spreading to nearby individuals
214	     * @param Probability of disease spreading to neighbours
215	     */
216	    protected void setInfectiousness(double prob) {
217	        infectiousness = prob;
218	    }
219	    
220	    /**
221	     * Method to set duration of how long a disease infects an individual 
222	     * before it is cured/dies
223	     * @param duration The number of days an infection lasts
224	     */
225	    protected void setDuration(int duration) {
226	        this.duration = duration;
227	    }
228	}

