  4	/**
  5	 * Models behaviour of simple weather conditions in the simulation.
  6	 * It can rain, be very hot or foggy, which in return affects how species behave.
  7	 *
  8	 * @version 2022.02.27
  9	 */
 10	public class Weather implements Actor
 11	{
 12	    // Probability of rain occurring
 13	    private static final double RAIN_PROB = 0.12;
 14	    // Probability of fog occurring
 15	    private static final double FOG_PROB = 0.005;
 16	    // Probability of a heatwave occurring 
 17	    private static final double HEATWAVE_PROB = 0.0001;
 18	    // Indicates whether new water sources need to be generated
 19	    private boolean generateWater = false;
 20	
 21	    /**
 22	     * Constructor for objects of class Weather
 23	     */
 24	    public Weather() {}
 25	
 26	    /**
 27	     * Advance the weather by one lifecycle tick.
 28	     * @param context Shared lifecycle state for the current step.
 29	     */
 30	    @Override
 31	    public void tick(SimulationContext context) {
 32	        generateWater = false;
 33	        // Generate one weather event per step using shared randomness.
 34	        Random rand = Randomizer.getRandom();
 35	        if (rand.nextDouble() <= RAIN_PROB) {
 36	            makeRain(context.getActors());
 37	            generateWater = true;
 38	            context.requestWaterGeneration();
 39	        }
 40	        else if (rand.nextDouble() <= FOG_PROB){
 41	            makeFog(context.getActors());
 42	        }
 43	        else if (rand.nextDouble() <= HEATWAVE_PROB) {
 44	            makeHeatWave(context.getActors());
 45	        }
 46	    }
 47	
 48	    /**
 49	     * What happens when rain occurs. 
 50	     * Water value for all objects are increased by 5, which is the water value of rain.
 51	     * This in turn affects each object's behaviour.
 52	     * @param newActors A list to receive any species affected by the weather event
 53	     */
 54	    protected boolean makeRain(List<Actor> actorsList){
 55	        adjustMoisture(actorsList, 5, 10);
 56	        return true;
 57	    }
 58	
 59	    /**
 60	     * What happens when fog occurs. 
 61	     * Water value for some objects are increased by 2 
 62	     * and causes animals to not be able to conduct normal behaviour when there is gof.
 63	     * This in turn affects each object's behaviour.
 64	     * @param newActors A list to receive any species affected by the weather event
 65	     */
 66	    protected void makeFog(List<Actor> actorsList) {
 67	        for (Actor actor : actorsList) {
 68	            if (actor instanceof Plant) {
 69	                Plant plant = (Plant) actor;
 70	                plant.setWaterLevel(plant.getWaterLevel() + 2);
 71	            }
 72	            else if (actor instanceof Animal) {
 73	                Animal animal = (Animal) actor;
 74	                animal.setSleepStatus();
 75	            }
 76	            else if (actor instanceof WaterSources){
 77	                WaterSources source = (WaterSources) actor;
 78	                source.setVolume(source.getVolume() + 2);
 79	            }
 80	        }
 81	    }
 82	
 83	    /**
 84	     * What happens when a heatwave occurs. 
 85	     * Water value for all objects is halved by 2 to show impact of extreme exposure to heat.
 86	     * This in turn affects each object's behaviour.
 87	     * @param newActors A list to receive any species affected by the weather event
 88	     */
 89	    protected void makeHeatWave(List<Actor> actorsList){
 90	        for (Actor actor : actorsList) {
 91	            if (actor instanceof Plant) {
 92	                Plant plant = (Plant) actor;
 93	                plant.setWaterLevel(plant.getWaterLevel() / 2);
 94	            }
 95	            else if (actor instanceof Animal) {
 96	                Animal animal = (Animal) actor;
 97	                animal.setWaterLevel(animal.getWaterLevel() / 2);
 98	            }
 99	            else if (actor instanceof WaterSources){
100	                WaterSources source = (WaterSources) actor;
101	                source.setVolume(source.getVolume() / 2);
102	            }
103	        }
104	    }
105	
106	    /**
107	     * Increase hydration for living things and water volume for water sources.
108	     * @param actorsList The active actors.
109	     * @param organismDelta Water added to plants and animals.
110	     * @param waterDelta Water added to water sources.
111	     */
112	    private void adjustMoisture(List<Actor> actorsList, int organismDelta, int waterDelta)
113	    {
114	        for (Actor actor : actorsList) {
115	            if (actor instanceof Plant) {
116	                Plant plant = (Plant) actor;
117	                plant.setWaterLevel(plant.getWaterLevel() + organismDelta);
118	            }
119	            else if (actor instanceof Animal) {
120	                Animal animal = (Animal) actor;
121	                animal.setWaterLevel(animal.getWaterLevel() + organismDelta);
122	            }
123	            else if (actor instanceof WaterSources) {
124	                WaterSources source = (WaterSources) actor;
125	                source.setVolume(source.getVolume() + waterDelta);
126	            }
127	        }
128	    }
