  5	/**
  6	 * A class representing shared characteristics of animals.
  7	 *
  8	 * @version 2022.03.01
  9	 */
 10	public abstract class Animal extends Organism
 11	{
 12	    // Shared random source for animal lifecycle decisions.
 13	    private static final Random rand = Randomizer.getRandom();
 14	    // The level of food an animal has consumed, increases when it eats
 15	    private int foodLevel;
 16	    // Indicates whether an animal can give birth or not
 17	    private boolean female;
 18	    // Indicates whether the animal is nocturnal or not
 19	    private boolean nocturnal;
 20	    // Indicates whether the animal is sleeping or not
 21	    private boolean sleeping;
 22	    
 23	    /**
 24	     * Create a new animal at location in field.
 25	     * 
 26	     * @param randomAge If true, the animal will have a random age
 27	     * @param field The field currently occupied.
 28	     * @param location The location within the field.
 29	     */
 30	    public Animal(boolean randomAge, Field field, Location location)
 31	    {
 32	        super(randomAge, field, location);
 33	        nocturnal = false;
 34	        female = rand.nextBoolean();
 35	        setWaterLevel(rand.nextInt(10) + 5);
 36	        sleeping = false;
 37	        if(!randomAge) {
 38	            setAge(0);
 39	            foodLevel = rand.nextInt(10) + 8;
 40	        }
 41	    }
 42	    
 43	    /**
 44	     * Advance the animal by one lifecycle tick.
 45	     * @param context Shared lifecycle state for the current step.
 46	     */
 47	    @Override
 48	    public void tick(SimulationContext context) {
 49	        if (context.isNightTime() != isNocturnal()) {
 50	            return;
 51	        }
 52	
 53	        super.tick(context);
 54	        incrementHunger();
 55	        if(isAlive() && !sleeping) {        
 56	            // Move towards a source of food if found
 57	            giveBirth(context.getSpawnedActors());  
 58	            Location newLocation = null;
 59	            newLocation = findWater();
 60	            if (newLocation == null && getFoodLevel() < 8 && rand.nextDouble() <= getHuntProbability()) {
 61	                newLocation = findFood(getPrey());
 62	            }
 63	            if (newLocation == null) {
 64	                newLocation = findMate();
 65	            }
 66	            if(newLocation == null) { 
 67	                // No food found - try to move to a free location.
 68	                newLocation = getField().freeAdjacentLocation(getLocation());
 69	            }
 70	            
 71	            // See if it was possible to move.
 72	            if(newLocation != null) {
 73	                setLocation(newLocation);
 74	            }
 75	            else {
 76	                // Overcrowding.
 77	                setDead();
 78	            }
 79	        }
 80	        else if (sleeping) {
 81	            // code for what to do when sleeping
 82	            sleeping = false;
 83	        }
 84	    }
 85	    
 86	    /**
 87	     * Move towards another animal of the same species to find a mate to breed with
 88	     * 
 89	     * @return The location of a potential mate if found, null if not
 90	     */
 91	    protected Location findMate() 
 92	    {
 93	        if (hasCompatibleMateAdjacent()) {
 94	            return getField().freeAdjacentLocation(getLocation());
 95	        }
 96	        return null;
 97	    }
 98	
 99	    /**
100	     * Look for prey adjacent to the current location.
101	     * Only the first live prey is eaten.
102	     * @return Where food was found, or null if it wasn't.
103	     */
104	    protected Location findFood(List<String> preyList)
105	    {
106	        Field field = getField();
107	        List<Location> adjacent = field.adjacentLocations(getLocation());
108	        Iterator<Location> it = adjacent.iterator();
109	        while(it.hasNext()) {
110	            Location where = it.next();
111	            Object food = field.getObjectAt(where);
112	            if(food!= null) {
113	                if(preyList.contains(food.getClass().getName())) {
114	                    Organism prey = (Organism) food;
115	                    if(prey.isAlive()) { 
116	                        prey.setDead();
117	                        int increment = prey.getFoodValue() + this.getFoodLevel();
118	                        this.setFoodLevel(increment);
119	                        changeWaterLevel(5);
120	                        return where;  
121	                    }
122	                }
123	            }
124	        }
125	        return null;
126	    }
127	    
128	    /**
129	     * Make the animal more hungry. This could result in the animal's death.
130	     */
131	    private void incrementHunger()
132	    {
133	        foodLevel--;
134	        if(foodLevel <= 0) {
135	            setDead();
136	        }
137	    }
138	    
139	    /**
140	     * Check whether or not this animal is to give birth at this step.
141	     * New births will be made into free adjacent locations.
142	     * @param newAnimals A list to return newly born animals.
143	     */
144	    protected void giveBirth(List<Actor> newAnimals)
145	    {
146	        int births = breed();
147	        if (births <= 0) {
148	            return;
149	        }
150	
151	        List<Location> free = getBirthLocations();
152	        if (free == null) {
153	            return;
154	        }
155	
156	        Field field = getField();
157	        for(int b = 0; b < births && free.size() > 0; b++) {
158	            Location loc = free.remove(0);
159	            Organism young = createOffspring(field, loc);
160	            initializeOffspring(young);
161	            newAnimals.add(young);
162	        }
163	    }
164	
165	    /**
166	     * Find free adjacent locations for births if a compatible mate is nearby.
167	     * @return The free locations available for offspring, or null if breeding is not possible.
168	     */
169	    protected List<Location> getBirthLocations()
170	    {
171	        if (hasCompatibleMateAdjacent()) {
172	            return getField().getFreeAdjacentLocations(getLocation());
173	        }
174	        return null;
175	    }
176	    
177	    /**
178	     * @param foodValue The level of food an animal has eaten
179	     */
180	    protected void setFoodLevel(int foodValue)
181	    {
182	        foodLevel = foodValue;
183	    }
184	    
185	    /** 
186	     * @return The level of food an animal has eaten
187	     */
188	    protected int getFoodLevel()
189	    {
190	        return foodLevel;
191	    }
192	    
193	    /** 
194	     * @return True if this animal is a female, capable of breeding
195	     */
196	    public boolean isFemale()
197	    {
198	        return female;
199	    }
200	    
201	    /** 
202	     * @return True if this animal is a female, capable of breeding
203	     */
204	    protected void setNocturnal()
205	    {
206	        nocturnal = true;
207	    }
208	    
209	    /** 
210	     * @return True if this animal is nocturnal, false if not
211	     */
212	    public boolean isNocturnal()
213	    {
214	        return nocturnal;
215	    }
216	    
217	    /**
218	     * Sets the sleeping boolean variable to the opposite state it currently has.
219	     */
220	    protected void setSleepStatus(){
221	        sleeping = ! sleeping;
222	    }
223	    
224	    /**
225	     * @return Returns list of prey for each animal
226	     */
227	    abstract public List<String> getPrey();
228	
229	    /**
230	     * @return The probability that this animal successfully hunts when it is hungry.
231	     */
232	    protected double getHuntProbability()
233	    {
234	        return 1.0;
235	    }
236	
237	    /**
238	     * @return The age at which this animal can breed.
239	     */
240	    protected abstract int getBreedingAge();
241	
242	    /**
243	     * @return The chance this animal successfully breeds when it can breed.
244	     */
245	    protected abstract double getBreedingProbability();
246	
247	    /**
248	     * @return The maximum litter size for this animal.
249	     */
250	    protected abstract int getMaxLitterSize();
251	
252	    /**
253	     * Create a new offspring of the current species.
254	     * @param field The field the offspring should occupy.
255	     * @param location The offspring's location.
256	     * @return A new instance of the same species.
257	     */
258	    protected abstract Organism createOffspring(Field field, Location location);
259	
