  4	/**
  5	 * A class representing shared characteristics of plants.
  6	 *
  7	 * @version 2022.02.28
  8	 */
  9	public abstract class Plant extends Organism
 10	{
 11	    // Shared random source for plant lifecycle decisions.
 12	    private static final Random rand = Randomizer.getRandom();
 13	
 14	    /**
 15	     * Create a new plant at location in field.
 16	     * @param randomAge If true, the plant will have a random age assigned to it.
 17	     * @param field The field currently occupied.
 18	     * @param location The location within the field.
 19	     */
 20	    public Plant(boolean randomAge, Field field, Location location)
 21	    {
 22	        super(randomAge, field, location);
 23	        setAge(0);
 24	        setWaterLevel(rand.nextInt(getStartingWaterLevelUpperBound()));
 25	        if(randomAge) {
 26	            setAge(rand.nextInt(getMaxAge()));
 27	        }
 28	    }
 29	
 30	    /**
 31	     * Advance the plant by one lifecycle tick.
 32	     * @param context Shared lifecycle state for the current step.
 33	     */
 34	    @Override
 35	    public void tick(SimulationContext context)
 36	    {
 37	        super.tick(context);
 38	        if (isAlive()) {
 39	            giveBirth(context.getSpawnedActors());
 40	            findWater();
 41	        }
 42	    }
 43	
 44	    /**
 45	     * Check whether or not this plant is to give birth at this step.
 46	     * New growths will be made into free adjacent locations.
 47	     * @param newPlants A list to return newly grown plants.
 48	     */
 49	    protected void giveBirth(List<Actor> newPlants)
 50	    {
 51	        int births = breed();
 52	        if (births <= 0) {
 53	            return;
 54	        }
 55	
 56	        List<Location> free = getBirthLocations();
 57	        if (free == null) {
 58	            return;
 59	        }
 60	
 61	        Field field = getField();
 62	        for(int b = 0; b < births && free.size() > 0; b++) {
 63	            Location loc = free.remove(0);
 64	            Organism young = createOffspring(field, loc);
 65	            initializeOffspring(young);
 66	            newPlants.add(young);
 67	        }
 68	    }
 69	
 70	    /**
 71	     * Find free adjacent locations for births if this plant can breed.
 72	     */
 73	    protected List<Location> getBirthLocations()
 74	    {
 75	        if (canBreed()) {
 76	            return getField().getFreeAdjacentLocations(getLocation());
 77	        }
 78	        return null;
 79	    }
 80	
 81	    /**
 82	     * Determine whether this plant can currently breed.
 83	     */
 84	    private boolean canBreed()
 85	    {
 86	        return getWaterLevel() >= getBreedingWaterThreshold();
 87	    }
 88	
 89	    /**
 90	     * Generate the number of offspring produced by this plant.
 91	     */
 92	    private int breed()
 93	    {
 94	        if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
 95	            return rand.nextInt(getMaxLitterSize()) + 1;
 96	        }
 97	        return 0;
 98	    }
 99	
100	    /**
101	     * @return The probability that this plant reproduces when conditions are met.
102	     */
103	    protected abstract double getBreedingProbability();
104	
105	    /**
