107	     */
108	    protected abstract int getMaxLitterSize();
109	
110	    /**
111	     * @return The minimum water level required to reproduce.
112	     */
113	    protected abstract int getBreedingWaterThreshold();
114	
115	    /**
116	     * @return The upper bound used for initial water level generation.
117	     */
118	    protected abstract int getStartingWaterLevelUpperBound();
